def find_all_hollow_frames(grid, ignore_colors=(0,9)):
    """Find hollow rectangular frames"""
    h, w = len(grid), len(grid[0])
    frames = []

    for r1 in range(h):
        for c1 in range(w):
            color = grid[r1][c1]
            if color in ignore_colors:
                continue

            # Find extent of this color
            rmin, rmax, cmin, cmax = r1, r1, c1, c1
            for r in range(h):
                for c in range(w):
                    if grid[r][c] == color:
                        rmin = min(rmin, r)
                        rmax = max(rmax, r)
                        cmin = min(cmin, c)
                        cmax = max(cmax, c)

            height = rmax - rmin + 1
            width = cmax - cmin + 1

            # Check if it's a hollow frame (border exists, interior may be different)
            if height >= 3 and width >= 3:
                # Verify it's hollow - all cells on border should be this color
                is_hollow = True
                for r in range(rmin, rmax+1):
                    for c in range(cmin, cmax+1):
                        if (r == rmin or r == rmax or c == cmin or c == cmax):
                            if grid[r][c] != color:
                                is_hollow = False
                                break

                if is_hollow:
                    # Get interior
                    interior_cells = set()
                    for r in range(rmin+1, rmax):
                        for c in range(cmin+1, cmax):
                            interior_cells.add((r,c))

                    interior_values = [grid[r][c] for r,c in interior_cells]

                    frames.append({
                        'color': color,
                        'rmin': rmin, 'rmax': rmax, 'cmin': cmin, 'cmax': cmax,
                        'width': width, 'height': height,
                        'interior_size': len(interior_cells),
                        'interior_values': interior_values,
                        'unique_interior_values': set(interior_values)
                    })

    return frames

