def find_hollow_frames(grid):
    """Find all hollow rectangular frames"""
    h, w = len(grid), len(grid[0])
    frames = []

    # Scan for potential top-left corners of frames
    # A frame starts where we have color X in position (r,c) and 
    # there exist cells at (r,c+w-1), (r+h-1,c), (r+h-1,c+w-1) all with color X

    for r in range(h - 3):  # Need at least 3x3
        for c in range(w - 3):
            color = grid[r][c]
            if color == 0 or color == 9:
                continue

            # Check each possible size starting from 3
            for size in [3, 4, 5, 6, 7, 8, 9, 10]:  # Up to reasonable size
                if r + size > h or c + size > w:
                    break

                # Check if all four corners have this color
                corners_ok = True
                for dr, dc in [(0,0),(0,size-1),(size-1,0),(size-1,size-1)]:
                    if grid[r+dr][c+dc] != color:
                        corners_ok = False
                        break

                if not corners_ok:
                    continue

                # Now check if ALL border cells have this color
                # AND ALL interior cells do NOT have this color (to be a proper hollow frame)

                border_all_color = True
                for i in range(size):
                    # Top row
                    for j in range(size):
                        if grid[r+i][c+j] != color:
                            border_all_color = False
                    # Bottom row
                    if not border_all_color:
                        break
                    for j in range(size):
                        if grid[r+size-1-i][c+(size-1-j)] != color:
                            border_all_color = False

                if not border_all_color:
                    continue

                # Check interior doesn't have frame color
                interior_has_color = False
                for ir in range(r+1, r+size-1):
                    for ic in range(c+1, c+size-1):
                        if grid[ir][ic] == color:
                            interior_has_color = True
                            break
                    if interior_has_color:
                        break

                if interior_has_color:
                    continue

                # Also check that interior is non-empty (frame must have actual interior)
                interior_size = (size-2)*(size-2)
                if interior_size == 0:
                    continue

                # Valid frame! Record it
                frame_idx = len(frames)
                frames.append({
                    'index': frame_idx,
                    'color': color,
                    'r': r, 'c': c,
                    'size': size,
                    'width': size, 'height': size,
                    'interior_size': interior_size,
                    'interior_start': (r+1, c+1),
                    'interior_end': (r+size-2, c+size-2),
                })

    return frames

