def find_all_hollow_frames(grid):
    """Find all hollow rectangular frames, ensuring no nested/duplicate detection"""
    h, w = len(grid), len(grid[0])
    visited_cells = set()
    frames = []

    # Scan for top-left corners of potential frames
    for r in range(h - 2):
        for c in range(w - 2):
            # Skip if this cell is already part of another frame's border
            if (r,c) in visited_cells:
                continue

            color = grid[r][c]
            if color == 0 or color == 9:
                continue

            # Check each possible size starting from 3
            for size in [3, 4, 5, 6, 7, 8, 9, 10]:
                if r + size > h or c + size > w:
                    break

                # Must start with corner having the color
                if grid[r][c] != color:
                    continue

                # Quick check: verify all four corners exist and match
                if not (grid[r+size-1][c] == color and 
                        grid[r][c+size-1] == color and 
                        grid[r+size-1][c+size-1] == color):
                    continue

                # Now verify ALL border cells have this color
                is_hollow = True
                for i in range(size):
                    # Top row
                    for j in range(size):
                        if grid[r+i][c+j] != color:
                            is_hollow = False
                    # Bottom row  
                    if not is_hollow:
                        break
                    for j in range(size):
                        if grid[r+size-1-i][c+(size-1-j)] != color:
                            is_hollow = False

                if not is_hollow:
                    continue

                # Verify interior doesn't have frame color
                has_interior_color = False
                for ir in range(r+1, r+size-1):
                    for ic in range(c+1, c+size-1):
                        if grid[ir][ic] == color:
                            has_interior_color = True
                            break
                    if has_interior_color:
                        break

                if has_interior_color:
                    continue

                # Mark all border cells as visited
                for i in range(size):
                    visited_cells.add((r+i, c))
                    visited_cells.add((r+i, c+size-1))
                for j in range(1, size-1):
                    visited_cells.add((r, c+j))
                    visited_cells.add((r+size-1, c+j))

                # Record frame
                frames.append({
                    'color': color,
                    'r': r, 'c': c,
                    'width': size, 'height': size,
                    'interior_size': (size-2)*(size-2),
                })

    return frames

