def get_changed_regions(grid_in, grid_out):
    h, w = len(grid_in), len(grid_in[0])
    visited = set()
    regions = []

    for r in range(h):
        for c in range(w):
            if grid_in[r][c] != grid_out[r][c]:
                if (r,c) not in visited:
                    region = [(r,c)]
                    queue = [(r,c)]

                    while queue:
                        cr, cc = queue.pop(0)
                        for dr, dc in [(-1,0),(1,0),(0,-1),(0,1)]:
                            nr, nc = cr + dr, cc + dc
                            if 0 <= nr < h and 0 <= nc < w:
                                if grid_in[nr][nc] != grid_out[nr][nc] and (nr,nc) not in visited:
                                    visited.add((nr,nc))
                                    region.append((nr,nc))
                                    queue.append((nr,nc))

                    regions.append(region)

    return regions

