def select_non_overlapping_frames(frames, priority='size_desc'):
    """Select non-overlapping frames based on priority"""
    if priority == 'size_desc':
        sorted_frames = sorted(frames, key=lambda f: (-f['int_size'], str(f['pos'])))
    else:
        sorted_frames = sorted(frames, key=lambda f: (-f['size'], str(f['pos'])))

    selected = []
    for fr in sorted_frames:
        pr, pc = fr['pos']
        sr, sc = pr + fr['size'] - 1, pc + fr['size'] - 1

        # Check if any selected frame overlaps with this one
        overlap = False
        for sel in selected:
            spr, scc = sel['pos']
            ssr, ssc = spr + sel['size'] - 1, scc + sel['size'] - 1
            # Interior overlap
            if not (pr >= ssr or sr <= spr or pc >= ssc or sc <= spr):
                overlap = True
                break

        if not overlap:
            selected.append(fr)

    return selected

