def analyze_fill_logic(grid, cell_r, cell_c, expected_fill):
    """Find containing frames and analyze their fill logic"""
    h, w = len(grid), len(grid[0])

    results = []
    for sz in [3, 4, 5]:
        for fr_r in range(max(0, cell_r - 2), min(h, cell_r+sz)):
            for fr_c in range(max(0, cell_c - 2), min(w, cell_c+sz)):
                # Check if this position could be a frame corner that contains the cell
                tr = fr_r + sz - 1
                tc = fr_c + sz - 1

                # Make sure frame contains the cell strictly
                if not (fr_r < cell_r < tr and fr_c < cell_c < tc):
                    continue

                color = grid[fr_r][fr_c]
                if color == 0:
                    continue

                # Verify it's a valid hollow frame
                if not (grid[tr][fr_c] == color and grid[fr_r][tc] == color and grid[tr][tc] == color):
                    continue

                ok = True
                for j in range(sz):
                    if grid[fr_r+j][fr_c] != color or grid[fr_r+j][tc] != color:
                        ok = False; break
                if not ok: continue
                for i_f in range(1, sz):
                    if grid[fr_r+i_f][fr_c] != color or grid[fr_r+i_f][tc] != color:
                        ok = False; break
                if not ok: continue

                # Get interior color(s)
                int_vals = set()
                for ir in range(fr_r+1, tr):
                    for ic in range(fr_c+1, tc):
                        int_vals.add(grid[ir][ic])

                actual_int_color = list(int_vals)[0] if len(int_vals) == 1 else "multi"
                predicted_fill = 2 if actual_int_color == color else 7

                results.append({
                    'frame': (fr_r, fr_c, sz),
                    'border_color': color,
                    'interior_val': actual_int_color,
                    'match': actual_int_color == color,
                    'pred_fill': predicted_fill
                })

    return results

